#ifdef GL_ES
precision mediump float;
#endif

#define u_resolution iResolution.xy
#define u_time iTime


void mainImage(out vec4 fragColor, in vec2 fragCoord)
{

    // Default values for curvature equation coefficients
    float u_a  = 0.0;  // Base lateral shift
    float u_b  = 0.0;  // Linear coefficient
    float u_c  = 0.2;  // Quadratic coefficient
    float u_d1 = 0.000; // Cubic coefficient for first segment
    float u_d2 = -0.000; // Cubic coefficient for second segment
    float u_s1 = 1.0;  // Segment boundary s1
    float u_s2 = 1.0;  // Segment boundary s2

    // Speed input (in km/h)
    float u_speed = 60.0;  // Default speed (60 km/h)

    // Road appearance settings
    float u_lineWidth = 0.06;  // Side lane width
    float u_middleLaneWidth = 0.04;  // Middle lane width
    float u_dotHeight = 0.2;  // Dotted line height
    int u_numLanes = 3;  // Number of lanes
    bool u_sideLeftDotted = false;  // Left side dotted line option
    bool u_sideRightDotted = false; // Right side dotted line option

    // Colors
    vec3 u_roadColor = vec3(0.1, 0.1, 0.1);
    vec3 u_sideLeftLineColor = vec3(1.0, 0.0, 0.0);
    vec3 u_sideRightLineColor = vec3(1.0, 0.0, 0.0);
    vec3 u_dotLineColor = vec3(1.0, 1.0, 0.0);

    // Normalized coordinates
    vec2 uv = fragCoord / u_resolution;
    uv.x = (uv.x - 0.5) * 2.0; 
    uv.y = (uv.y - 0.5) * 2.0;

    // Convert speed from km/h to a motion factor
    float speedFactor = u_speed * 0.01;  // Scale speed effect
    float movingOffset = mod(u_time * speedFactor, u_dotHeight * 2.0);  // Controls movement

    // Define piecewise curve based on the given formula
    float x = uv.y;  
    float curve = 0.0;

    if (x < u_s1) {
        curve = u_a + u_b * x + u_c * x * x + u_d1 * x * x * x;
    } else if (x < u_s2) {
        curve = u_a + u_b * x + u_c * x * x + u_d2 * x * x * x;
    }

    uv.x -= curve;  // Apply road curvature

    // Road dimensions
    float roadWidth = 0.9;  
    float laneWidth = (roadWidth * 2.0) / float(u_numLanes);
    float sideLineWidth = u_lineWidth * 0.5;
    float middleLaneWidth = u_middleLaneWidth * 0.5;

    // Moving dashed line pattern
    float dashedPattern = step(0.5, fract((uv.y + movingOffset) / u_dotHeight));

    vec3 color = u_roadColor;

    // Render lane markings
    float middleLine = 0.0;
    for (int i = 0; i < u_numLanes; i++) {
        float lanePos = -roadWidth + laneWidth * float(i);
        float laneLine = 1.0 - step(middleLaneWidth * 0.5, abs(uv.x - lanePos));
        middleLine += laneLine * dashedPattern;
    }

    // Side lines (solid or dotted)
    float sideLeft = 1.0 - step(sideLineWidth * 0.5, abs(uv.x - (-roadWidth)));
    float sideRight = 1.0 - step(sideLineWidth * 0.5, abs(uv.x - roadWidth));

    float sideLeftDottedPattern = u_sideLeftDotted ? dashedPattern : 1.0;
    float sideRightDottedPattern = u_sideRightDotted ? dashedPattern : 1.0;

    // Mix colors
    color = mix(color, u_dotLineColor, middleLine);
    color = mix(color, u_sideLeftLineColor, sideLeft * sideLeftDottedPattern);
    color = mix(color, u_sideRightLineColor, sideRight * sideRightDottedPattern);

    fragColor = vec4(color, 1.0);
}
